from math import log, sqrt, exp, erf

def norm_cdf(x):
    return 0.5 * (1 + erf(x / sqrt(2)))

def bs_call(S, K, r, sigma, tau):
    d1 = (log(S/K) + (r + 0.5*sigma**2)*tau) / (sigma*sqrt(tau))
    d2 = d1 - sigma*sqrt(tau)
    return S*norm_cdf(d1) - K*exp(-r*tau)*norm_cdf(d2)

def implied_vol(market_price, S, K, r, tau, lo=0.001, hi=3.0, tol=1e-6):
    for _ in range(100):
        mid = (lo + hi) / 2
        price = bs_call(S, K, r, mid, tau)
        if abs(price - market_price) < tol:
            return mid
        if price > market_price:
            hi = mid
        else:
            lo = mid
    return mid

S, r, tau = 24000, 0.07, 0.25
quotes = {22000: 2436.85, 23000: 1532.46, 24000: 778.93, 25000: 296.77, 26000: 79.15}

for K, price in quotes.items():
    iv = implied_vol(price, S, K, r, tau)
    print(f"Strike {K}: implied vol = {iv:.1%}")

